const state={
 locale:localStorage.getItem('ghostftp.locale')||'en',
 sites:JSON.parse(localStorage.getItem('ghostftp.sites')||'[]'),
 settings:JSON.parse(localStorage.getItem('ghostftp.settings')||'{"theme":"dark","density":"comfortable","concurrent":4,"retries":3,"autoResume":true,"rememberPasswords":true,"noTracking":true}'),
 local:[],remote:[],selected:{local:null,remote:null},transfers:[],log:[]
};
function t(k){return (D[state.locale]&&D[state.locale][k])||EN[k]||k}
function translate(root=document){document.documentElement.lang=state.locale;$$('[data-i18n]',root).forEach(el=>{const k=el.dataset.i18n;el.textContent=t(k)});}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function notify(m){toast.textContent=m;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2100)}
function log(m,ok=false){const tm=new Date().toLocaleTimeString('en-GB',{hour12:false});state.log.push({text:`${tm}  ${m}`,ok});if(state.log.length>100)state.log.shift();renderLog()}
function persistedSites(){
 return state.sites.map(site=>{
  const {password,pass,keyPath,privateKey,privateKeyPath,passphrase,...safe}=site||{};
  return safe;
 });
}
function persistLocalState(){
 localStorage.setItem('ghostftp.locale',state.locale);
 localStorage.setItem('ghostftp.sites',JSON.stringify(persistedSites()));
 localStorage.setItem('ghostftp.settings',JSON.stringify(state.settings));
}
async function persistServerState(){
 if(!sessionToken)return;
 try{await api('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({locale:state.locale,sites:persistedSites(),settings:state.settings})})}catch(e){log(`State save warning: ${e.message||e}`)}
}
function saveSites(){persistLocalState();void persistServerState()}
function saveSettings(){persistLocalState();void persistServerState()}
async function initSession(){
 const r=await fetch('/api/session',{cache:'no-store',credentials:'same-origin'});
 if(!r.ok)throw new Error(`Session initialization failed (${r.status})`);
 const v=await r.json();sessionToken=String(v.token||'');
 if(!sessionToken)throw new Error('Local session token is unavailable');
}
async function restoreServerState(){
 try{
  const v=await api('/api/state');
  if(!v.ok)return;
  if(Array.isArray(v.sites))state.sites=v.sites;
  if(v.settings&&typeof v.settings==='object'&&!Array.isArray(v.settings))state.settings={...state.settings,...v.settings};
  if(typeof v.locale==='string'&&LANGS.some(([id])=>id===v.locale))state.locale=v.locale;
  persistLocalState();
 }catch(e){log(`State load warning: ${e.message||e}`)}
}
function fmtSize(n){if(!n)return '';const u=['B','KB','MB','GB','TB'];let i=0,v=n;while(v>=1024&&i<u.length-1){v/=1024;i++}return `${v<10&&i? v.toFixed(1):Math.round(v)} ${u[i]}`}
function fmtDate(s){try{return new Date(s).toLocaleString(state.locale,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}catch{return ''}}
function typeFor(x){if(x.dir)return t('folder');const e=x.name.split('.').pop()?.toUpperCase();return e&&e!==x.name.toUpperCase()?`${e} File`:'File'}
function svg(id){return `<svg><use href="#${id}"/></svg>`}
function renderSites(){
 const list=$('#siteList'), empty=$('#siteEmpty');
 list.innerHTML=state.sites.map((s,i)=>`<button class="site-row${connected&&s.host===$('#host').value?' active':''}" data-site="${i}">${svg('i-server')}<span>${esc(s.name||s.host)}</span><b class="site-led"></b></button>`).join('');
 empty.style.display=state.sites.length?'none':'flex';$$('[data-site]',list).forEach(b=>b.onclick=()=>loadSite(+b.dataset.site));
}
function renderFiles(){
 const local=$('#localFiles'); local.innerHTML=state.local.map((x,i)=>fileRow(x,'local',i)).join('');
 const remote=$('#remoteFiles'); remote.innerHTML=state.remote.map((x,i)=>fileRow(x,'remote',i)).join('');
 $$('.file-row').forEach(r=>{r.onclick=()=>{state.selected[r.dataset.pane]=+r.dataset.index;activePane=r.dataset.pane;renderFiles()};r.ondblclick=()=>{const pane=r.dataset.pane,i=+r.dataset.index,x=state[pane][i];if(x?.dir&&pane==='local')loadLocal(x.path)}});
 $('#localSummary').textContent=`${state.local.length} ${t('items')}`;$('#remoteSummary').textContent=`${state.remote.length} ${t('items')}`;
 $('[data-pane="remote"]').classList.toggle('remote-empty',!connected||!state.remote.length);$('#remoteEmpty').style.display=!connected?'grid':'none';
}
