async function api(path,opts={}){
 const init={...opts,credentials:'same-origin'};
 const method=String(init.method||'GET').toUpperCase();
 const headers=new Headers(init.headers||{});
 if(method!=='GET'&&method!=='HEAD'){
  if(!sessionToken)throw new Error('Local session is not initialized');
  headers.set('X-GhostFTP-Token',sessionToken);
 }
 init.headers=headers;
 const r=await fetch(path,init);
 const ct=r.headers.get('content-type')||'';
 const payload=ct.includes('application/json')?await r.json():{ok:false,error:(await r.text()).trim()||`HTTP ${r.status}`};
 if(!r.ok)throw new Error(payload.error||payload.message||`HTTP ${r.status}`);
 return payload;
}
