async function loadLocal(path){try{const v=await api('/api/fs/list?path='+encodeURIComponent(path||''));if(!v.ok)throw new Error(v.error);state.local=v.items||[];$('#localPath').value=v.path||path||'';state.selected.local=null;renderFiles()}catch(e){log(e.message);notify(e.message)}}
function loadSite(i){const s=state.sites[i];if(!s)return;$('#host').value=s.host||'';$('#user').value=s.user||'';$('#port').value=s.port||21;$('#remotePath').value=s.path||'/';openNewConnection(s,i)}
