async function newFolder(){if(activePane!=='local'){if(!connected)notify(t('connectionRequired'));return}const base=$('#localPath').value,name=prompt(t('newFolder'));if(!name)return;const sep=base.includes('\\')?'\\':'/';const v=await api('/api/fs/mkdir',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:base.replace(/[\\/]$/,'')+sep+name})});if(v.ok){notify(t('folderCreated'));loadLocal(base)}else notify(v.error||'Error')}
