function openProperties(){
 const x=requireSelection();if(!x)return;const isLocal=activePane==='local';
 const mode=(x.mode||'').slice(-9).padStart(9,'-');const bit=(i)=>mode[i]&&mode[i]!=='-';
 openOverlay(`<section class="dialog properties-dialog">${dialogHeader(t('propertiesTitle'))}<div class="property-tabs"><button class="active" data-ptab="general">${t('generalTab')}</button><button data-ptab="checksums">${t('checksums')}</button></div><div class="dialog-body"><div id="propGeneral"><div class="property-file">${svg(x.dir?'i-folder':'i-file')}<div><h2>${esc(x.name)}</h2><p>${esc(typeFor(x))}</p></div></div><div class="property-list"><label>${t('path')}<input id="propPath" value="${esc(x.path||$('#localPath').value+'/'+x.name)}" readonly></label><label>${t('size')}<span>${esc(fmtSize(x.size||0)||'—')}</span></label><label>${t('modified')}<span>${esc(fmtDate(x.modified))}</span></label></div><hr><div class="grid2"><label class="field">${t('owner')}<input value="${esc(x.owner||'—')}" readonly></label><label class="field">${t('group')}<input value="${esc(x.group||'—')}" readonly></label></div><div class="chmod-head"><h3>${t('permissions')}</h3><label>${t('numeric')} <input id="chmodNumeric" value="000" maxlength="3" inputmode="numeric"></label></div><div class="permissions-grid" id="permGrid"><b></b><b>${t('read')}</b><b>${t('write')}</b><b>${t('execute')}</b><span>${t('owner')}</span><input data-bit="0" type="checkbox" ${bit(0)?'checked':''}><input data-bit="1" type="checkbox" ${bit(1)?'checked':''}><input data-bit="2" type="checkbox" ${bit(2)?'checked':''}><span>${t('group')}</span><input data-bit="3" type="checkbox" ${bit(3)?'checked':''}><input data-bit="4" type="checkbox" ${bit(4)?'checked':''}><input data-bit="5" type="checkbox" ${bit(5)?'checked':''}><span>${t('others')}</span><input data-bit="6" type="checkbox" ${bit(6)?'checked':''}><input data-bit="7" type="checkbox" ${bit(7)?'checked':''}><input data-bit="8" type="checkbox" ${bit(8)?'checked':''}></div><div class="sync-options"><h3>${t('syncOptions')}</h3><label><input id="propRecursive" type="checkbox"> ${t('recursive')}</label><label><input type="checkbox" checked> ${t('preserveTransfer')}</label><label><input type="checkbox" checked> ${t('includeSync')}</label></div></div><div id="propChecksums" hidden><div class="checksum-panel"><h3>SHA-256</h3><p>${x.dir?t('checksumUnavailable'):'SHA-256'}</p><div class="checksum-value" id="checksumValue">${x.dir?'—':t('select')}</div>${x.dir?'':`<button class="primary" id="checksumCalc">${t('checksums')}</button>`}</div></div></div><footer class="dialog-foot"><button class="small" id="propOpen">${t('openFolder')}</button><button class="small" id="propDuplicate">${t('duplicate')}</button><span></span><button class="small" data-close>${t('cancel')}</button><button class="primary" id="propApply" ${isLocal?'':'disabled'}>${t('apply')}</button></footer></section>`,root=>{
  const checks=$$('[data-bit]',root),numeric=$('#chmodNumeric',root),path=x.path||$('#localPath').value+'/'+x.name;function modeNum(){const vals=[0,0,0];checks.forEach((c,i)=>{if(c.checked)vals[Math.floor(i/3)]+=[4,2,1][i%3]});return vals.join('')}function syncNumeric(){numeric.value=modeNum()}checks.forEach(c=>c.onchange=syncNumeric);syncNumeric();numeric.oninput=()=>{const v=numeric.value.replace(/[^0-7]/g,'').slice(0,3);numeric.value=v;if(v.length===3){[...v].forEach((n,g)=>{const val=+n;checks[g*3].checked=!!(val&4);checks[g*3+1].checked=!!(val&2);checks[g*3+2].checked=!!(val&1)})}};
  $$('[data-ptab]',root).forEach(btn=>btn.onclick=()=>{$$('[data-ptab]',root).forEach(x=>x.classList.toggle('active',x===btn));$('#propGeneral',root).hidden=btn.dataset.ptab!=='general';$('#propChecksums',root).hidden=btn.dataset.ptab!=='checksums'});const calc=$('#checksumCalc',root);if(calc)calc.onclick=async()=>{const box=$('#checksumValue',root);box.textContent='…';const r=await api('/api/fs/checksum',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});box.textContent=r.ok?r.sha256:(r.error||t('checksumUnavailable'));if(r.ok)notify(t('checksumReady'))};$('#propOpen',root).onclick=async()=>{const r=await api('/api/fs/open',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});if(!r.ok)notify(r.error||'Error')};$('#propDuplicate',root).onclick=async()=>{if(!isLocal){notify(t('connectionRequired'));return}const r=await api('/api/fs/duplicate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});if(r.ok){closeOverlay();await loadLocal($('#localPath').value);notify(t('saved'))}else notify(r.error||'Error')};$('#propApply',root).onclick=async()=>{const v=numeric.value;if(v.length!==3){notify(t('permissions'));return}const r=await api('/api/fs/chmod',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,mode:parseInt(v,8),recursive:$('#propRecursive',root).checked})});if(r.ok){closeOverlay();await loadLocal($('#localPath').value);notify(t('saved'))}else notify(r.error||'Error')}
 })
}
